@page "/settings"
@using sv_84ddd83ace83455dba6eeb7772bc27f8.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <ul>
            <li class="@(activeSection == "Profile" ? "active" : "")" @onclick='() => SetSection("Profile")'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(activeSection == "Notifications" ? "active" : "")" @onclick='() => SetSection("Notifications")'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(activeSection == "Security" ? "active" : "")" @onclick='() => SetSection("Security")'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(activeSection == "Appearance" ? "active" : "")" @onclick='() => SetSection("Appearance")'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (!string.IsNullOrEmpty(toastMessage))
        {
            <div class="toast @toastType">
                @toastMessage
                <button class="toast-close" @onclick="DismissToast">✕</button>
            </div>
        }

        @if (activeSection == "Profile")
        {
            <section class="settings-section">
                <h2>Profile Settings</h2>
                @if (profile is not null)
                {
                    <div class="profile-layout">
                        <div class="avatar-area">
                            <img src="@editDisplayAvatarUrl" alt="Avatar" class="avatar-preview" />
                            <p class="avatar-url-label">@editDisplayAvatarUrl</p>
                        </div>
                        <div class="profile-fields">
                            <div class="form-group">
                                <label for="displayName">Display Name</label>
                                <input id="displayName" type="text" @bind="editDisplayName" />
                            </div>
                            <div class="form-group">
                                <label for="email">Email</label>
                                <input id="email" type="email" @bind="editEmail" />
                            </div>
                            <div class="form-group">
                                <label for="bio">Bio</label>
                                <textarea id="bio" rows="4" @bind="editBio"></textarea>
                            </div>
                            <div class="form-group">
                                <label for="avatarUrl">Avatar URL</label>
                                <input id="avatarUrl" type="url" @bind="editDisplayAvatarUrl" />
                            </div>
                            <div class="button-group">
                                <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                                <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
                            </div>
                        </div>
                    </div>
                }
            </section>
        }
        else if (activeSection == "Notifications")
        {
            <section class="settings-section">
                <h2>Notification Preferences</h2>
                @if (notificationPrefs is not null)
                {
                    <div class="toggle-group">
                        <label class="toggle-label">
                            <span>Email Notifications</span>
                            <label class="switch">
                                <input type="checkbox" @bind="editEmailNotifications" />
                                <span class="slider"></span>
                            </label>
                        </label>
                        <label class="toggle-label">
                            <span>Push Notifications</span>
                            <label class="switch">
                                <input type="checkbox" @bind="editPushNotifications" />
                                <span class="slider"></span>
                            </label>
                        </label>
                        <label class="toggle-label">
                            <span>Weekly Digest</span>
                            <label class="switch">
                                <input type="checkbox" @bind="editWeeklyDigest" />
                                <span class="slider"></span>
                            </label>
                        </label>
                    </div>

                    <h3>Muted Channels</h3>
                    <div class="channel-list">
                        @foreach (var channel in editMutedChannels)
                        {
                            <label class="channel-item">
                                <input type="checkbox" checked="@channel.IsMuted"
                                       @onchange="(e) => ToggleChannel(channel.Name, (bool)(e.Value ?? false))" />
                                <span>#@channel.Name</span>
                            </label>
                        }
                    </div>

                    <div class="button-group">
                        <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
                    </div>
                }
            </section>
        }
        else if (activeSection == "Security")
        {
            <section class="settings-section">
                <h2>Security Settings</h2>
                @if (securitySettings is not null)
                {
                    <div class="expandable-panel">
                        <button class="panel-header" @onclick="TogglePasswordPanel">
                            <span>Change Password</span>
                            <span class="expand-icon">@(showPasswordPanel ? "▼" : "▶")</span>
                        </button>
                        @if (showPasswordPanel)
                        {
                            <div class="panel-body">
                                <div class="form-group">
                                    <label for="currentPassword">Current Password</label>
                                    <input id="currentPassword" type="password" @bind="currentPassword" />
                                </div>
                                <div class="form-group">
                                    <label for="newPassword">New Password</label>
                                    <input id="newPassword" type="password" @bind="newPassword" />
                                </div>
                                <div class="form-group">
                                    <label for="confirmPassword">Confirm Password</label>
                                    <input id="confirmPassword" type="password" @bind="confirmPassword" />
                                </div>
                                @if (!string.IsNullOrEmpty(passwordError))
                                {
                                    <p class="error-text">@passwordError</p>
                                }
                                <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                            </div>
                        }
                    </div>

                    <div class="toggle-group" style="margin-top: 1.5rem;">
                        <label class="toggle-label">
                            <span>
                                Two-Factor Authentication
                                <span class="status-indicator @(securitySettings.TwoFactorEnabled ? "status-on" : "status-off")">
                                    @(securitySettings.TwoFactorEnabled ? "Enabled" : "Disabled")
                                </span>
                            </span>
                            <label class="switch">
                                <input type="checkbox" checked="@securitySettings.TwoFactorEnabled" disabled />
                                <span class="slider"></span>
                            </label>
                        </label>
                    </div>

                    @if (securitySettings.LastPasswordChange.HasValue)
                    {
                        <p class="info-text">Last password change: @securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                    }

                    <h3>Active Sessions</h3>
                    <div class="sessions-table-wrapper">
                        <table class="sessions-table">
                            <thead>
                                <tr>
                                    <th>Device</th>
                                    <th>Location</th>
                                    <th>Last Active</th>
                                    <th>Action</th>
                                </tr>
                            </thead>
                            <tbody>
                                @foreach (var session in securitySettings.Sessions)
                                {
                                    <tr>
                                        <td>@session.Device</td>
                                        <td>@session.Location</td>
                                        <td>@FormatLastActive(session.LastActive)</td>
                                        <td>
                                            @if (session.Id == currentSessionId)
                                            {
                                                <span class="current-session-badge">Current</span>
                                            }
                                            else
                                            {
                                                <button class="btn btn-danger btn-sm" @onclick="() => ConfirmRevoke(session)">Revoke</button>
                                            }
                                        </td>
                                    </tr>
                                }
                            </tbody>
                        </table>
                    </div>

                    @if (showRevokeConfirmation && sessionToRevoke is not null)
                    {
                        <div class="modal-overlay" @onclick="CancelRevoke">
                            <div class="modal" @onclick:stopPropagation="true">
                                <h3>Revoke Session</h3>
                                <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke.Device</strong> from <strong>@sessionToRevoke.Location</strong>?</p>
                                <div class="button-group">
                                    <button class="btn btn-danger" @onclick="RevokeSession">Yes, Revoke</button>
                                    <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                                </div>
                            </div>
                        </div>
                    }
                }
            </section>
        }
        else if (activeSection == "Appearance")
        {
            <section class="settings-section">
                <h2>Appearance Settings</h2>
                @if (appearance is not null)
                {
                    <div class="form-group">
                        <label>Theme</label>
                        <div class="radio-group">
                            <label class="radio-label">
                                <input type="radio" name="theme" value="Light" checked="@(editTheme == "Light")" @onchange='() => editTheme = "Light"' />
                                <span>☀️ Light</span>
                            </label>
                            <label class="radio-label">
                                <input type="radio" name="theme" value="Dark" checked="@(editTheme == "Dark")" @onchange='() => editTheme = "Dark"' />
                                <span>🌙 Dark</span>
                            </label>
                            <label class="radio-label">
                                <input type="radio" name="theme" value="System" checked="@(editTheme == "System")" @onchange='() => editTheme = "System"' />
                                <span>💻 System</span>
                            </label>
                        </div>
                    </div>

                    <div class="form-group">
                        <label>Font Size</label>
                        <div class="radio-group">
                            <label class="radio-label">
                                <input type="radio" name="fontSize" value="Small" checked="@(editFontSize == "Small")" @onchange='() => editFontSize = "Small"' />
                                <span>Small</span>
                            </label>
                            <label class="radio-label">
                                <input type="radio" name="fontSize" value="Medium" checked="@(editFontSize == "Medium")" @onchange='() => editFontSize = "Medium"' />
                                <span>Medium</span>
                            </label>
                            <label class="radio-label">
                                <input type="radio" name="fontSize" value="Large" checked="@(editFontSize == "Large")" @onchange='() => editFontSize = "Large"' />
                                <span>Large</span>
                            </label>
                        </div>
                    </div>

                    <div class="form-group">
                        <label for="language">Language</label>
                        <select id="language" @bind="editLanguage">
                            <option value="English">English</option>
                            <option value="Spanish">Spanish</option>
                            <option value="French">French</option>
                            <option value="German">German</option>
                            <option value="Japanese">Japanese</option>
                            <option value="Chinese">Chinese</option>
                        </select>
                    </div>

                    <div class="toggle-group">
                        <label class="toggle-label">
                            <span>Compact Mode</span>
                            <label class="switch">
                                <input type="checkbox" @bind="editCompactMode" />
                                <span class="slider"></span>
                            </label>
                        </label>
                    </div>

                    <h3>Live Preview</h3>
                    <div class="live-preview @GetPreviewClasses()">
                        <div class="preview-header">
                            <h4>Preview Panel</h4>
                            <span class="preview-badge">@editTheme Theme</span>
                        </div>
                        <p class="preview-text">This is how your content will look with the selected settings.</p>
                        <div class="preview-meta">
                            <span>Font: @editFontSize</span>
                            <span>Lang: @editLanguage</span>
                            <span>Compact: @(editCompactMode ? "On" : "Off")</span>
                        </div>
                    </div>

                    <div class="button-group">
                        <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
                    </div>
                }
            </section>
        }
    </main>
</div>

@code {
    private string activeSection = "Profile";

    // Toast
    private string? toastMessage;
    private string toastType = "toast-success";

    // Profile
    private UserProfile? profile;
    private string editDisplayName = "";
    private string editEmail = "";
    private string editBio = "";
    private string editDisplayAvatarUrl = "";

    // Notifications
    private NotificationPrefs? notificationPrefs;
    private bool editEmailNotifications;
    private bool editPushNotifications;
    private bool editWeeklyDigest;
    private List<ChannelState> editMutedChannels = new();

    // Security
    private SecuritySettings? securitySettings;
    private string currentSessionId = "session-1";
    private bool showPasswordPanel;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string? passwordError;
    private bool showRevokeConfirmation;
    private ActiveSession? sessionToRevoke;

    // Appearance
    private AppearanceSettings? appearance;
    private string editTheme = "Light";
    private string editFontSize = "Medium";
    private string editLanguage = "English";
    private bool editCompactMode;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfile();
        await LoadNotifications();
        await LoadSecurity();
        await LoadAppearance();
    }

    private void SetSection(string section) => activeSection = section;

    // --- Profile ---
    private async Task LoadProfile()
    {
        profile = await SettingsService.GetProfileAsync();
        ResetProfileFields();
    }

    private void ResetProfileFields()
    {
        if (profile is null) return;
        editDisplayName = profile.DisplayName;
        editEmail = profile.Email;
        editBio = profile.Bio;
        editDisplayAvatarUrl = profile.AvatarUrl;
    }

    private async Task SaveProfile()
    {
        var updated = new UserProfile(editDisplayName, editEmail, editDisplayAvatarUrl, editBio);
        await SettingsService.SaveProfileAsync(updated);
        profile = updated;
        ShowToast("Profile saved successfully!", "toast-success");
    }

    private void DiscardProfileChanges()
    {
        ResetProfileFields();
        ShowToast("Changes discarded.", "toast-info");
    }

    // --- Notifications ---
    private async Task LoadNotifications()
    {
        notificationPrefs = await SettingsService.GetNotificationPrefsAsync();
        editEmailNotifications = notificationPrefs.EmailNotifications;
        editPushNotifications = notificationPrefs.PushNotifications;
        editWeeklyDigest = notificationPrefs.WeeklyDigest;
        editMutedChannels = notificationPrefs.MutedChannels
            .Select(c => new ChannelState(c, true))
            .ToList();
    }

    private void ToggleChannel(string name, bool isMuted)
    {
        var ch = editMutedChannels.FirstOrDefault(c => c.Name == name);
        if (ch is not null) ch.IsMuted = isMuted;
    }

    private async Task SaveNotifications()
    {
        var mutedList = editMutedChannels.Where(c => c.IsMuted).Select(c => c.Name).ToList();
        var updated = new NotificationPrefs(editEmailNotifications, editPushNotifications, editWeeklyDigest, mutedList);
        await SettingsService.SaveNotificationPrefsAsync(updated);
        notificationPrefs = updated;
        ShowToast("Notification preferences saved!", "toast-success");
    }

    // --- Security ---
    private async Task LoadSecurity()
    {
        securitySettings = await SettingsService.GetSecuritySettingsAsync();
    }

    private void TogglePasswordPanel() => showPasswordPanel = !showPasswordPanel;

    private async Task UpdatePassword()
    {
        passwordError = null;
        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            passwordError = "All fields are required.";
            return;
        }
        if (newPassword != confirmPassword)
        {
            passwordError = "New password and confirmation do not match.";
            return;
        }
        if (newPassword.Length < 8)
        {
            passwordError = "Password must be at least 8 characters.";
            return;
        }

        await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
        currentPassword = "";
        newPassword = "";
        confirmPassword = "";
        showPasswordPanel = false;
        securitySettings = await SettingsService.GetSecuritySettingsAsync();
        ShowToast("Password updated successfully!", "toast-success");
    }

    private void ConfirmRevoke(ActiveSession session)
    {
        sessionToRevoke = session;
        showRevokeConfirmation = true;
    }

    private void CancelRevoke()
    {
        sessionToRevoke = null;
        showRevokeConfirmation = false;
    }

    private async Task RevokeSession()
    {
        if (sessionToRevoke is null) return;
        await SettingsService.RevokeSessionAsync(sessionToRevoke.Id);
        securitySettings = await SettingsService.GetSecuritySettingsAsync();
        showRevokeConfirmation = false;
        sessionToRevoke = null;
        ShowToast("Session revoked.", "toast-success");
    }

    private string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }

    // --- Appearance ---
    private async Task LoadAppearance()
    {
        appearance = await SettingsService.GetAppearanceAsync();
        editTheme = appearance.Theme;
        editFontSize = appearance.FontSize;
        editLanguage = appearance.Language;
        editCompactMode = appearance.CompactMode;
    }

    private async Task SaveAppearance()
    {
        var updated = new AppearanceSettings(editTheme, editFontSize, editLanguage, editCompactMode);
        await SettingsService.SaveAppearanceAsync(updated);
        appearance = updated;
        ShowToast("Appearance settings saved!", "toast-success");
    }

    private string GetPreviewClasses()
    {
        var classes = $"preview-{editTheme.ToLower()} preview-font-{editFontSize.ToLower()}";
        if (editCompactMode) classes += " preview-compact";
        return classes;
    }

    // --- Toast ---
    private void ShowToast(string message, string type)
    {
        toastMessage = message;
        toastType = type;
        _ = DismissToastAfterDelay();
    }

    private async Task DismissToastAfterDelay()
    {
        await Task.Delay(3000);
        toastMessage = null;
        await InvokeAsync(StateHasChanged);
    }

    private void DismissToast() => toastMessage = null;

    // Helper class
    private class ChannelState
    {
        public string Name { get; set; }
        public bool IsMuted { get; set; }
        public ChannelState(string name, bool isMuted) { Name = name; IsMuted = isMuted; }
    }
}

.settings-container {
    display: flex;
    min-height: calc(100vh - 4rem);
    max-width: 1200px;
    margin: 0 auto;
    gap: 0;
    border: 1px solid #e2e8f0;
    border-radius: 8px;
    overflow: hidden;
    background: #fff;
}

/* Sidebar */
.settings-sidebar {
    width: 220px;
    background: #f8fafc;
    border-right: 1px solid #e2e8f0;
    padding: 1rem 0;
    flex-shrink: 0;
}

.settings-sidebar ul {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-sidebar li {
    padding: 0.75rem 1.25rem;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 0.5rem;
    font-weight: 500;
    color: #475569;
    border-left: 3px solid transparent;
    transition: all 0.15s ease;
}

.settings-sidebar li:hover {
    background: #e2e8f0;
    color: #1e293b;
}

.settings-sidebar li.active {
    background: #e0e7ff;
    color: #4338ca;
    border-left-color: #4338ca;
}

.nav-icon {
    font-size: 1.1rem;
}

/* Content area */
.settings-content {
    flex: 1;
    padding: 2rem;
    position: relative;
}

.settings-section h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    color: #1e293b;
    font-size: 1.5rem;
}

.settings-section h3 {
    margin-top: 1.5rem;
    margin-bottom: 0.75rem;
    color: #334155;
}

/* Form elements */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: #374151;
    font-size: 0.9rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="url"],
.form-group input[type="password"],
.form-group textarea,
.form-group select {
    width: 100%;
    padding: 0.6rem 0.75rem;
    border: 1px solid #d1d5db;
    border-radius: 6px;
    font-size: 0.95rem;
    transition: border-color 0.15s;
    box-sizing: border-box;
}

.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
    outline: none;
    border-color: #6366f1;
    box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.1);
}

/* Buttons */
.button-group {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

.btn {
    padding: 0.6rem 1.2rem;
    border: none;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.15s;
}

.btn-primary {
    background: #4f46e5;
    color: #fff;
}

.btn-primary:hover {
    background: #4338ca;
}

.btn-secondary {
    background: #e2e8f0;
    color: #475569;
}

.btn-secondary:hover {
    background: #cbd5e1;
}

.btn-danger {
    background: #ef4444;
    color: #fff;
}

.btn-danger:hover {
    background: #dc2626;
}

.btn-sm {
    padding: 0.35rem 0.75rem;
    font-size: 0.8rem;
}

/* Profile layout */
.profile-layout {
    display: flex;
    gap: 2rem;
}

.avatar-area {
    text-align: center;
    flex-shrink: 0;
}

.avatar-preview {
    width: 120px;
    height: 120px;
    border-radius: 50%;
    object-fit: cover;
    border: 3px solid #e2e8f0;
}

.avatar-url-label {
    font-size: 0.75rem;
    color: #64748b;
    max-width: 140px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    margin-top: 0.5rem;
}

.profile-fields {
    flex: 1;
}

/* Toggle switches */
.toggle-group {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.toggle-label {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.75rem 1rem;
    background: #f8fafc;
    border-radius: 8px;
    border: 1px solid #e2e8f0;
}

.switch {
    position: relative;
    display: inline-block;
    width: 44px;
    height: 24px;
    flex-shrink: 0;
}

.switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.slider {
    position: absolute;
    cursor: pointer;
    inset: 0;
    background-color: #cbd5e1;
    transition: 0.2s;
    border-radius: 24px;
}

.slider::before {
    content: "";
    position: absolute;
    height: 18px;
    width: 18px;
    left: 3px;
    bottom: 3px;
    background-color: white;
    transition: 0.2s;
    border-radius: 50%;
}

.switch input:checked + .slider {
    background-color: #4f46e5;
}

.switch input:checked + .slider::before {
    transform: translateX(20px);
}

/* Channels */
.channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.5rem 0.75rem;
    background: #f8fafc;
    border-radius: 6px;
    cursor: pointer;
}

.channel-item input[type="checkbox"] {
    accent-color: #4f46e5;
}

/* Expandable panel */
.expandable-panel {
    border: 1px solid #e2e8f0;
    border-radius: 8px;
    overflow: hidden;
}

.panel-header {
    width: 100%;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1rem 1.25rem;
    background: #f8fafc;
    border: none;
    cursor: pointer;
    font-size: 1rem;
    font-weight: 500;
    color: #1e293b;
}

.panel-header:hover {
    background: #f1f5f9;
}

.panel-body {
    padding: 1.25rem;
    border-top: 1px solid #e2e8f0;
}

.error-text {
    color: #ef4444;
    font-size: 0.85rem;
    margin: 0.5rem 0;
}

.info-text {
    color: #64748b;
    font-size: 0.85rem;
    margin-top: 1rem;
}

/* Status indicator */
.status-indicator {
    font-size: 0.75rem;
    padding: 0.2rem 0.5rem;
    border-radius: 9999px;
    margin-left: 0.5rem;
    font-weight: 600;
}

.status-on {
    background: #dcfce7;
    color: #166534;
}

.status-off {
    background: #fee2e2;
    color: #991b1b;
}

/* Sessions table */
.sessions-table-wrapper {
    overflow-x: auto;
}

.sessions-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.9rem;
}

.sessions-table th,
.sessions-table td {
    padding: 0.75rem 1rem;
    text-align: left;
    border-bottom: 1px solid #e2e8f0;
}

.sessions-table th {
    background: #f8fafc;
    font-weight: 600;
    color: #475569;
}

.current-session-badge {
    font-size: 0.75rem;
    padding: 0.2rem 0.6rem;
    background: #dbeafe;
    color: #1e40af;
    border-radius: 9999px;
    font-weight: 500;
}

/* Modal */
.modal-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.modal {
    background: white;
    padding: 2rem;
    border-radius: 12px;
    max-width: 420px;
    width: 90%;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.2);
}

.modal h3 {
    margin-top: 0;
}

/* Radio group */
.radio-group {
    display: flex;
    gap: 1.25rem;
    flex-wrap: wrap;
}

.radio-label {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
    padding: 0.5rem 1rem;
    border: 1px solid #e2e8f0;
    border-radius: 6px;
    transition: all 0.15s;
}

.radio-label:has(input:checked) {
    border-color: #4f46e5;
    background: #eef2ff;
}

.radio-label input[type="radio"] {
    accent-color: #4f46e5;
}

/* Live preview */
.live-preview {
    border: 1px solid #e2e8f0;
    border-radius: 8px;
    padding: 1.5rem;
    margin-top: 0.75rem;
    transition: all 0.2s;
}

.live-preview .preview-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.live-preview .preview-header h4 {
    margin: 0;
}

.preview-badge {
    font-size: 0.75rem;
    padding: 0.2rem 0.6rem;
    background: #e0e7ff;
    color: #4338ca;
    border-radius: 9999px;
}

.preview-meta {
    display: flex;
    gap: 1rem;
    margin-top: 0.75rem;
    font-size: 0.8rem;
    color: #64748b;
}

/* Preview variants */
.preview-light {
    background: #ffffff;
    color: #1e293b;
    border-color: #e2e8f0;
}

